const results = [];

for (const item of $input.all()) {
  for (const [key, file] of Object.entries(item.binary || {})) {

    if (
      file.mimeType === 'application/pdf' ||
      file.fileName?.toLowerCase().endsWith('.pdf')
    ) {
      results.push({
        json: {
          message_id: item.json.id,
          thread_id: item.json.threadId,
          subject: item.json.subject || item.json.headers?.subject,
          sender: item.json.from || item.json.headers?.from,
          file_name: file.fileName,
          file_type: file.mimeType,
          original_attachment_key: key
        },
        binary: {
          data: file
        }
      });
    }
  }
}

return results;

return $input.all().map((item) => {
  const invoice = item.json.output;
  const errors = [];
  const warnings = [];

  const isMoney = value =>
    typeof value === 'number' && Number.isFinite(value);

  const round = value => Math.round(value * 100);

  const validDate = value => {
    if (typeof value !== 'string' ||
        !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;

    const date = new Date(value);

    return !isNaN(date.getTime()) &&
      date.toISOString().slice(0, 10) === value;
  };

  // 1. Document classification
  if (invoice.document_type !== 'invoice') {
    errors.push('Document is not a supplier invoice');
  }

  // 2. Required information
  const requiredFields = [
    'supplier_name',
    'customer_name',
    'invoice_number',
    'invoice_date',
    'currency'
  ];

  for (const field of requiredFields) {
    if (!invoice[field]) {
      errors.push(`Missing required field: ${field}`);
    }
  }

  // 3. Validate invoice total
  if (!isMoney(invoice.total_amount) ||
      invoice.total_amount < 0) {
    errors.push('Invalid invoice total');
  }

  // 4. Validate balance due
  if (invoice.balance_due == null) {
    warnings.push('Balance due not explicitly stated');
  } else if (!isMoney(invoice.balance_due) ||
             invoice.balance_due < 0) {
    errors.push('Invalid balance due');
  } else if (invoice.balance_due > invoice.total_amount) {
    warnings.push('Balance due exceeds invoice total');
  }

  // 5. Validate dates
  if (!validDate(invoice.invoice_date)) {
    errors.push('Invalid invoice date');
  }

  if (!invoice.due_date) {
    warnings.push('Payment due date not specified');
  } else if (!validDate(invoice.due_date)) {
    errors.push('Invalid payment due date');
  } else if (invoice.due_date < invoice.invoice_date) {
    errors.push('Due date precedes invoice date');
  }

  // 6. Check end-of-month payment terms
  if (
    validDate(invoice.invoice_date) &&
    validDate(invoice.due_date) &&
    /^due end of the month$/i.test(
      invoice.payment_terms?.trim() || ''
    )
  ) {
    const [year, month] = invoice.invoice_date
      .split('-').map(Number);

    const expectedDate = new Date(
      Date.UTC(year, month, 0)
    ).toISOString().slice(0, 10);

    if (invoice.due_date !== expectedDate) {
      warnings.push(
        'Payment terms conflict with stated due date'
      );
    }
  }

  // 7. Validate totals where VAT is stated
  if (
    isMoney(invoice.subtotal) &&
    isMoney(invoice.vat_amount) &&
    isMoney(invoice.total_amount)
  ) {
    if (
      Math.abs(
        round(invoice.subtotal) +
        round(invoice.vat_amount) -
        round(invoice.total_amount)
      ) > 1
    ) {
      warnings.push('Subtotal and VAT do not match total');
    }
  }

  // 8. Validate line item totals
  const lines = invoice.line_items || [];

  if (lines.length === 0) {
    warnings.push('No line items extracted');
  }

  for (const line of lines) {
    if (
      isMoney(line.quantity) &&
      isMoney(line.unit_price) &&
      isMoney(line.amount)
    ) {
      if (
        Math.abs(
          round(line.quantity * line.unit_price) -
          round(line.amount)
        ) > 1
      ) {
        warnings.push(
          `Line item mismatch: ${line.description}`
        );
      }
    }
  }

  // 9. Determine validation status
  const status = errors.length > 0
    ? 'failed'
    : warnings.length > 0
      ? 'review_required'
      : 'passed';

  return {
    json: {
      ...invoice,
      validation_status: status,
      validation_errors: errors,
      validation_warnings: warnings,
      validated_at: new Date().toISOString()
    }
  };
});

return $input.all().map(item => {
  const invoice = item.json;

  const normalize = value =>
    String(value || '')
      .trim()
      .toLowerCase()
      .replace(/\s+/g, ' ');

  const invoiceKey = JSON.stringify([
    normalize(invoice.supplier_name),
    normalize(invoice.customer_name),
    normalize(invoice.invoice_number)
  ]);

  return {
    json: {
      ...invoice,
      invoice_key: invoiceKey,
      approval_status: 'pending',
      payment_status: 'unverified',
      payment_date: null,
      payment_reference: null,
      processed_at: new Date().toISOString()
    }
  };
});

const invoice = $('Generate Invoice Key').first().json;

return [{
  json: {
    ...invoice,
    validation_warnings: 
      invoice.validation_warnings.join('; ')
  }
}];

const invoice = $input.first().json;
const original = $('Filter PDF Attachments').first();

if (!original.binary?.data) {
  throw new Error('Original invoice PDF not found');
}

return [{
  json: {
    ...invoice,
    pdf_file_name: original.json.file_name,
    source_message_id: original.json.message_id
  },
  binary: {
    data: original.binary.data
  }
}];

const invoice = $('Restore Invoice PDF').first().json;
const file = $input.first().json;

if (!file.id) {
  throw new Error('Google Drive file ID missing');
}

return [{
  json: {
    ...invoice,
    pdf_file_name: file.name || invoice.pdf_file_name,
    pdf_file_id: file.id,
    pdf_url: file.webViewLink ||
      `https://drive.google.com/file/d/${file.id}/view`,
    source_message_id: invoice.source_message_id,
    approval_requested_at: new Date().toISOString()
  }
}];

