const invoice = $('Prepare Final Record').first().json;
const approval = $input.first().json;

if (approval.approval_status !== 'approved') {
  throw new Error('Invoice approval could not be verified');
}

return [{
  json: {
    ...invoice,
    approval_status: 'approved',
    approval_decided_at: approval.approval_decided_at
  }
}];
